findings.codeql_raw_query:
/**
 * @name Windows registry access with untrusted input
 * @description User input flowing into Windows registry operations without validation
 * @kind path-problem
 * @problem.severity warning
 * @id py/windows-registry-injection
 * @tags security
 *        external/cwe/cwe-276
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module RegistryInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("winreg").getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegistryInjectionFlow = TaintTracking::Global<RegistryInjectionConfig>;
import RegistryInjectionFlow::PathGraph

from RegistryInjectionFlow::PathNode source, RegistryInjectionFlow::PathNode sink
where RegistryInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Windows registry injection vulnerability from $@.", source, "user input"
